<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Pato na Pista</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>
body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}header{background:#10283d;color:#fff;padding:14px 5vw;font-weight:900}main{max-width:1400px;margin:auto;padding:24px}.hero{display:flex;justify-content:space-between;align-items:center}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.95;letter-spacing:-.06em;margin:8px 0}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:20px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}textarea{width:100%;min-height:88px;box-sizing:border-box;border:2px solid #dbe5e8;border-radius:12px;padding:12px;font:inherit}button{border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;font-weight:900;cursor:pointer;margin:10px 8px 0 0}.secondary{background:#fff}.participants{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.pill{background:#d8f4f4;border-radius:999px;padding:7px 12px}.qr{display:flex;gap:18px;align-items:center}.qr canvas,.qr img{width:230px!important;height:230px!important;border:10px solid #fff}.race{background:#10283d;color:#d8f4f4;border-radius:14px;padding:14px;overflow:hidden}.track{height:58px;position:relative;border-bottom:1px dashed #6fc9d2;display:flex;align-items:center}.track:last-child{border-bottom:0}.track-label{width:175px;z-index:3;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.finish{position:absolute;right:5%;height:100%;border-left:3px solid #ffd45c;opacity:.7}.duck{position:absolute;left:0;z-index:2;font-size:32px;display:flex;align-items:center;gap:5px;white-space:nowrap}.duck em{font:800 12px system-ui;background:#fff;color:#10283d;padding:4px 7px;border-radius:999px}.racing .duck{animation:run var(--time) cubic-bezier(.12,.7,.2,1) var(--delay) forwards}@keyframes run{0%{left:0;transform:translateY(0) rotate(-6deg)}25%{transform:translateY(-7px) rotate(5deg)}50%{transform:translateY(2px) rotate(-5deg)}75%{transform:translateY(-5px) rotate(4deg)}100%{left:var(--finish);transform:translateY(0) rotate(0)}}.winner{background:#203d4d}.winner .duck em{background:#ffd45c}.results li{padding:8px;border-bottom:1px solid #ddd}.fullscreen{position:fixed;inset:0;background:#fffaf0;z-index:20;display:grid;place-items:center}.fullscreen .qr{display:block;text-align:center}.fullscreen .qr canvas,.fullscreen .qr img{width:min(62vh,520px)!important;height:min(62vh,520px)!important}.muted{color:#637780;font-size:14px}@media(max-width:760px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{display:block}.track-label{width:100px;font-size:12px}.qr canvas,.qr img{width:170px!important;height:170px!important}}
</style></head><body><header>PATO NA PISTA 🦆</header><main id="app"><div v-if="!race" class="hero"><div><small>CORRIDA COM QR CODE</small><h1>Quem cruza a linha primeiro?</h1><p>Crie uma sala e compartilhe o QR code.</p><button @click="createRace">Criar sala</button></div><div style="font-size:90px">🦆</div></div><template v-else><div class="hero"><div><small>SALA @{{ race.code }}</small><h1>Prepare os patos.</h1><p>@{{ race.names.length }} participantes cadastrados.</p></div><div style="font-size:90px">🦆</div></div><section class="panel"><div class="grid"><div class="full"><label>Participantes, um por linha</label><textarea v-model="textNames" @change="importNames"></textarea><div class="participants"><span v-for="name in race.names" class="pill">@{{ name }}</span></div></div><div><button @click="startRace" :disabled="running">@{{ running?'Corrida em andamento...':'Começar corrida' }}</button><button class="secondary" @click="openQr">QR em tela cheia</button><button class="secondary" @click="exportCsv">Exportar CSV</button></div><div class="qr"><div id="qrcode"></div><span class="muted">Escaneie para entrar<br>@{{ joinUrl }}</span></div></div></section><section class="panel"><h2>@{{ running?'🏁 Corrida em andamento':'Pista dos participantes' }}</h2><div class="race"><div class="track" v-for="(name,i) in race.names" :class="{winner:finished&&winner===name}"><span class="track-label">@{{ name }}</span><span class="finish"></span><span class="duck" :style="duckStyle(name,i)">🦆 <em>@{{ name }}</em></span></div></div><div v-if="race.results&&!running" class="results"><h2>🏆 Resultado final</h2><ol><li v-for="r in race.results"><strong>@{{ r.position }}º — @{{ r.name }}</strong></li></ol></div></section></template><div v-if="showQr" class="fullscreen"><div class="qr"><div><small>ESCANEIE PARA PARTICIPAR</small><h1>Pato na Pista</h1></div><div id="qrcodeFull"></div><button @click="showQr=false">Fechar tela cheia</button></div></div></main><script>const{createApp}=Vue;createApp({data(){return{race:null,textNames:'',joinUrl:'',poll:null,running:false,finished:false,showQr:false,order:[],winner:''}},mounted(){const c=location.pathname.split('/').filter(Boolean).pop();if(c&&c!=='')this.load(c)},methods:{async createRace(){this.race=await(await fetch('/api/races',{method:'POST'})).json();this.setup()},async load(c){const r=await fetch('/api/races/'+c);if(r.ok){this.race=await r.json();this.setup()}},setup(){this.textNames=(this.race.names||[]).join('\n');this.joinUrl=location.origin+'/join/'+this.race.code;history.replaceState({},'', '/races/'+this.race.code);setTimeout(()=>new QRCode(document.getElementById('qrcode'),{text:this.joinUrl,width:230,height:230}),50);this.poll=setInterval(async()=>{if(!this.running){this.race=await(await fetch('/api/races/'+this.race.code)).json();this.textNames=(this.race.names||[]).join('\n')}},2500)},duckStyle(name,i){const position=this.order.indexOf(name);const rank=position<0?i:position;return{'--finish':(78+Math.random()*12)+'%','--time':(3.2+rank*.32)+'s','--delay':(Math.random()*.22)+'s'}},openQr(){this.showQr=true;setTimeout(()=>new QRCode(document.getElementById('qrcodeFull'),{text:this.joinUrl,width:520,height:520}),50)},async importNames(){this.race=await(await fetch('/api/races/'+this.race.code+'/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({names:this.textNames.split(/\n|,|;/).map(x=>x.trim()).filter(Boolean)})})).json()},async startRace(){this.running=true;this.finished=false;const response=await fetch('/api/races/'+this.race.code+'/start',{method:'POST'});const next=await response.json();this.order=next.results.map(r=>r.name);this.winner=this.order[0];setTimeout(()=>{this.race=next;this.running=false;this.finished=true},5800)},exportCsv(){const a=document.createElement('a');a.href='data:text/csv,nome,posicao%0A'+this.race.results.map(r=>r.name+','+r.position).join('%0A');a.download='resultado.csv';a.click()}}}).mount('#app')</script></body></html>
